def factorial(n):
    if n <= 1:          # base case
        return 1
    return n * factorial(n - 1)

def sum_digits(n):
    if n < 10:          # base case: a single digit
        return n
    return n % 10 + sum_digits(n // 10)

def power(x, n):
    if n == 0:          # base case
        return 1.0
    if n < 0:
        return 1 / power(x, -n)
    return x * power(x, n - 1)

def count_matches(n):
    if n == 1:          # base case: the champion is decided
        return 0
    matches = n // 2
    next_round = n // 2 + n % 2     # winners plus the team with a free pass
    return matches + count_matches(next_round)

def bin_search(arr, t, lo, hi):
    if lo > hi:                 # base case: empty range
        return -1

    mid = (lo + hi) // 2
    if arr[mid] == t:
        return mid
    if t < arr[mid]:
        return bin_search(arr, t, lo, mid - 1)
    return bin_search(arr, t, mid + 1, hi)

def fib_memo(n, memo=None):
    if memo is None:        # a fresh dict per top-level call
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:              # base cases: F(0) = 0, F(1) = 1
        return n

    memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo)
    return memo[n]

def climb_stairs(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:              # base cases: 0 or 1 step left
        return 1

    # the last move was a 1-step or a 2-step
    memo[n] = climb_stairs(n - 1, memo) + climb_stairs(n - 2, memo)
    return memo[n]

def flatten_nested(data):
    result = []
    for item in data:
        if isinstance(item, list):
            result.extend(flatten_nested(item))     # recurse into the inner list
        else:
            result.append(item)
    return result
